  'Variant B': { rich_text: t(fmt(byId('B'))) },
  'Variant C': { rich_text: t(fmt(byId('C'))) },
  'Variants passed': { rich_text: t(r.passedIds.length ? r.passedIds.join(', ') : 'none') },
